#include "web_portal.h"
#include "lead_store.h"
#include <WiFi.h>
#include <WebServer.h>
#include <DNSServer.h>
#include "config.h"
extern FiberConfig config; static WebServer server(80); static DNSServer dns;
static String page(){String s="<!doctype html><html><head><meta name=viewport content='width=device-width,initial-scale=1'><title>FiberScout</title><style>body{font:16px system-ui;max-width:560px;margin:auto;padding:20px;color:#17202a}input,select{box-sizing:border-box;width:100%;padding:12px;margin:5px 0 13px;border:1px solid #9aa;border-radius:8px}button{width:100%;padding:14px;border:0;border-radius:8px;background:#1366d6;color:white;font-weight:700}.consent{display:flex;gap:10px;align-items:flex-start}.consent input{width:auto}</style></head><body><h1>Fiber Internet Available in Your Neighborhood?</h1><p>Interested in learning more about fiber internet service in your area? Request information or ask for a follow-up.</p><form method=post action=/submit>";s+="<label>First name *<input name=first maxlength=40 required autocomplete=given-name></label><label>Last name (optional)<input name=last maxlength=40 autocomplete=family-name></label><label>Mobile phone number or email address *<input name=contact maxlength=120 required></label><label>Street address (optional)<input name=address maxlength=120 autocomplete=street-address></label><label>Current internet provider (optional)<input name=provider maxlength=60></label><label>Approximate monthly internet bill (optional)<input name=bill maxlength=30></label><label>Preferred contact method<select name=preferred><option>Phone</option><option>Email</option><option>No preference</option></select></label><label>Interested in receiving more information?<select name=interested><option>Yes</option><option>No</option></select></label><label class=consent><input type=checkbox name=consent value=yes required><span>I agree that the FiberScout operator may use this information to respond to my request. This is voluntary and is not marketing SMS consent.</span></label><p>Collector: ";s+=config.collector; s+="</p><p>";s+=config.privacyNotice;s+="</p><button type=submit>Request information</button></form></body></html>";return s;}
static void landing(){server.send(200,"text/html",page());}
static void submit(){if(server.args()>10){server.send(413,"text/plain","Request too large");return;}Lead l;l.first=server.arg("first");l.last=server.arg("last");l.contact=server.arg("contact");l.address=server.arg("address");l.provider=server.arg("provider");l.bill=server.arg("bill");l.preferred=server.arg("preferred");l.interested=server.arg("interested");l.consent=server.hasArg("consent");String e;if(!appendLead(l,e)){server.send(400,"text/html","<h2>Request not saved</h2><p>"+e+"</p><a href='/'>Back</a>");return;}server.send(200,"text/html","<meta name=viewport content='width=device-width'><h2>Thank you! Your request has been received.</h2><p>Your request is stored locally and is pending synchronization.</p>");}
static void redirect(){server.sendHeader("Location","/",true);server.send(302,"text/plain","");}
void portalBegin(){WiFi.mode(WIFI_AP);WiFi.softAP(config.ssid.c_str());dns.start(53,"*",WiFi.softAPIP());server.on("/",HTTP_GET,landing);server.on("/submit",HTTP_POST,submit);server.on("/generate_204",HTTP_GET,redirect);server.on("/hotspot-detect.html",HTTP_GET,redirect);server.on("/connecttest.txt",HTTP_GET,redirect);server.on("/ncsi.txt",HTTP_GET,redirect);server.onNotFound(redirect);server.begin();}
void portalLoop(){dns.processNextRequest();server.handleClient();}
